    ThriftMetadata.ThriftList unionListMetadata = (ThriftMetadata.ThriftList) structWithUnions.fields.get(4);
    assertTrue(unionListMetadata.hasUnion());
    ThriftMetadata.ThriftSet unionSetMetadata = (ThriftMetadata.ThriftSet) structWithUnions.fields.get(5);
    assertTrue(unionSetMetadata.hasUnion());
    ThriftMetadata.ThriftMap keyUnionMapMetadata = (ThriftMetadata.ThriftMap) structWithUnions.fields.get(6);
    assertTrue(keyUnionMapMetadata.hasUnion());
    ThriftMetadata.ThriftMap valUnionMapMetadata = (ThriftMetadata.ThriftMap) structWithUnions.fields.get(7);
    assertTrue(valUnionMapMetadata.hasUnion());
    ThriftMetadata.ThriftMap unionMapMetadata = (ThriftMetadata.ThriftMap) structWithUnions.fields.get(8);
